export const FONT_DATA = {
  interRegular:
    "",
  interMedium:
    "",
  interSemiBold:
    "",
  interBold:
    "",
  bricolageBold:
    "",
} as const;

export type FontKey = keyof typeof FONT_DATA;

export function decodeFont(key: FontKey): ArrayBuffer {
  const binary = atob(FONT_DATA[key]);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}
